const body = $input.first().json.body || {};
let kind = 'other';
if (body.callback_query) kind = 'callback';
else if (body.message && (body.message.document || body.message.photo)) kind = 'file';
return [{ json: { kind, body } }];

const http = (options) => this.helpers.httpRequest(options);
const PRICING = JSON.parse($env.MODEL_PRICING || '{}');
const TELEGRAM_API = `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}`;

const telegram = (method, body) => http({ method: 'POST', url: `${TELEGRAM_API}/${method}`, body, json: true });
const say = (chatId, text, extra = {}) => telegram('sendMessage', { chat_id: chatId, text, ...extra });

const costOf = (model, tokensIn, tokensOut) => {
  const [priceIn, priceOut] = PRICING[model] || [0, 0];
  return Number(((tokensIn * priceIn + tokensOut * priceOut) / 1e6).toFixed(6));
};

async function callClaude(model, system, mime, b64, schema, maxTokens) {
  const media = mime === 'application/pdf' ? 'document' : 'image';
  const res = await http({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
    body: {
      model,
      max_tokens: maxTokens,
      system,
      tools: [{ name: 'record', description: 'Record the result', input_schema: schema }],
      tool_choice: { type: 'tool', name: 'record' },
      messages: [{
        role: 'user',
        content: [
          { type: media, source: { type: 'base64', media_type: mime, data: b64 } },
          { type: 'text', text: 'Process this document.' },
        ],
      }],
    },
    json: true,
    timeout: 90000,
  });
  const block = (res.content || []).find((c) => c.type === 'tool_use');
  if (!block) throw new Error('model returned no structured output');
  return { data: block.input, tokensIn: res.usage.input_tokens, tokensOut: res.usage.output_tokens };
}

async function chatCompletion(url, key, body) {
  const res = await http({
    method: 'POST',
    url,
    headers: { Authorization: `Bearer ${key}` },
    body,
    json: true,
    timeout: 90000,
  });
  return {
    data: JSON.parse(res.choices[0].message.content),
    tokensIn: res.usage.prompt_tokens,
    tokensOut: res.usage.completion_tokens,
  };
}

async function callOpenAI(model, system, mime, b64, schema, maxTokens) {
  const dataUrl = `data:${mime};base64,${b64}`;
  const part = mime === 'application/pdf'
    ? { type: 'file', file: { filename: 'document.pdf', file_data: dataUrl } }
    : { type: 'image_url', image_url: { url: dataUrl } };
  return chatCompletion('https://api.openai.com/v1/chat/completions', $env.OPENAI_API_KEY, {
    model,
    max_tokens: maxTokens,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: [part, { type: 'text', text: 'Process this document.' }] },
    ],
    response_format: { type: 'json_schema', json_schema: { name: 'record', schema } },
  });
}

// DeepSeek only offers JSON mode, so the schema goes into the prompt and validation enforces it
async function callDeepSeek(model, system, mime, b64, schema, maxTokens) {
  if (mime === 'application/pdf') throw new Error('DeepSeek does not accept PDF input');
  const instruction = `${system}\n\nRespond with a single JSON object that matches this JSON schema:\n${JSON.stringify(schema)}`;
  return chatCompletion('https://api.deepseek.com/chat/completions', $env.DEEPSEEK_API_KEY, {
    model,
    max_tokens: maxTokens,
    messages: [
      { role: 'system', content: instruction },
      {
        role: 'user',
        content: [
          { type: 'image_url', image_url: { url: `data:${mime};base64,${b64}` } },
          { type: 'text', text: 'Process this document.' },
        ],
      },
    ],
    response_format: { type: 'json_object' },
  });
}

const providerFor = (model) => (model.startsWith('claude') ? callClaude : model.startsWith('deepseek') ? callDeepSeek : callOpenAI);

// Tries the primary model twice, then the fallback model once
async function runLLM(step, system, mime, b64, schema, maxTokens) {
  const models = [$env.PRIMARY_MODEL, $env.PRIMARY_MODEL, $env.FALLBACK_MODEL].filter(Boolean);
  const usage = [];
  let lastError = 'no model configured';
  for (const model of models) {
    const started = Date.now();
    try {
      const r = await providerFor(model)(model, system, mime, b64, schema, maxTokens);
      usage.push({
        step, model, tokens_in: r.tokensIn, tokens_out: r.tokensOut,
        cost_usd: costOf(model, r.tokensIn, r.tokensOut), latency_ms: Date.now() - started,
      });
      return { data: r.data, model, usage };
    } catch (e) {
      lastError = e.message;
      usage.push({ step, model, tokens_in: 0, tokens_out: 0, cost_usd: 0, latency_ms: Date.now() - started });
    }
  }
  return { error: lastError, usage };
}

const fs = require('fs');
const { randomUUID } = require('crypto');

const MAX_BYTES = 5 * 1024 * 1024;
const MIME_EXT = { 'application/pdf': 'pdf', 'image/jpeg': 'jpg', 'image/png': 'png' };

const message = $input.first().json.body.message;
const chatId = message.chat.id;
const file = message.document
  || (message.photo && { ...message.photo[message.photo.length - 1], mime_type: 'image/jpeg' });

if (!file) {
  await say(chatId, 'Send a PDF, JPG or PNG document to process.');
  return [];
}
const mime = file.mime_type;
if (!MIME_EXT[mime]) {
  await say(chatId, 'Unsupported file type. Send a PDF, JPG or PNG.');
  return [];
}
if (file.file_size > MAX_BYTES) {
  await say(chatId, 'File is larger than 5MB. Send a smaller file.');
  return [];
}

const info = await telegram('getFile', { file_id: file.file_id });
const bytes = await http({
  method: 'GET',
  url: `https://api.telegram.org/file/bot${$env.TELEGRAM_BOT_TOKEN}/${info.result.file_path}`,
  encoding: 'arraybuffer',
  json: false,
});

const id = randomUUID();
const filePath = `/files/${id}.${MIME_EXT[mime]}`;
fs.writeFileSync(filePath, Buffer.from(bytes));
await say(chatId, 'Document received, processing...');

return [{
  json: {
    id,
    source: 'telegram',
    chat_id: chatId,
    mime,
    file_path: filePath,
    status: 'received',
    usage: [],
    created_at: new Date().toISOString(),
  },
}];

