const doc = $input.first().json;
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const spent = store.spend && store.spend.day === today ? store.spend.usd : 0;

if (spent >= Number($env.DAILY_COST_CAP_USD || 2)) {
  await say(doc.chat_id, 'Daily processing limit reached. Try again tomorrow.');
  return [];
}
return [{ json: doc }];

const doc = $input.first().json;
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const added = (doc.usage || []).reduce((sum, u) => sum + u.cost_usd, 0);

const base = store.spend && store.spend.day === today ? store.spend.usd : 0;
store.spend = { day: today, usd: base + added };
return [{ json: doc }];

const query = $input.first().json.body.callback_query;
const [decision, id] = String(query.data || '').split(':');
const valid = ['approve', 'reject'].includes(decision) && id;
if (!valid) return [];

return [{
  json: {
    id,
    decision,
    status: decision === 'approve' ? 'approved' : 'rejected',
    chat_id: query.message.chat.id,
    message_id: query.message.message_id,
    callback_id: query.id,
  },
}];

